/**
 * Helper: get current season based on month
 */
export function getCurrentSeason() {
  const month = new Date().getMonth() + 1 // 1-12
  if (month >= 11 || month <= 2) return 'winter'
  if (month >= 3 && month <= 5) return 'summer'
  return 'monsoon'
}

/**
 * Helper: get destinations for current season
 */
export function getSeasonalDestinations(limit = 8) {
  const season = getCurrentSeason()
  const filtered = destinations.filter(d =>
    d.season_best.includes(season) || d.season_best.includes('all-year')
  )
  return filtered.sort((a, b) => b.rating - a.rating).slice(0, limit)
}

/**
 * Helper: get popular destinations (top rated with many reviews)
 */
export function getPopularDestinations(limit = 6) {
  return [...destinations]
    .sort((a, b) => (b.rating * Math.log(b.review_count + 1)) - (a.rating * Math.log(a.review_count + 1)))
    .slice(0, limit)
}

/**
 * Search index for autocomplete
 */
export const destinationSearchIndex = destinations.map(d => ({
  id: d.id,
  name: d.name,
  state: d.state,
  type: 'destination',
  category: d.category,
  budget_range: d.budget_range,
  image_url: d.image_url,
  rating: d.rating,
}))

